const TZ = 'YOUR_CLINIC_TIMEZONE';
const now = new Date();
const nowIso = now.toISOString();
const weekOf = new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);

function asDate(value) { if (!value) return null; const d = new Date(value); return Number.isNaN(d.getTime()) ? null : d; }
function daysSince(value) { const d = asDate(value); if (!d) return null; return Math.floor((now - d) / 86400000); }
function daysUntil(value) { const d = asDate(value); if (!d) return null; return Math.ceil((d - now) / 86400000); }
function money(value) { const n = parseFloat(value || 0); return Number.isFinite(n) ? n : 0; }
function priorityFromScore(score) { if (score >= 80) return 'High'; if (score >= 55) return 'Medium'; return 'Low'; }
function dueDate(offsetDays) { const d = new Date(now); d.setDate(d.getDate() + offsetDays); return new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(d); }
function pushOpportunity(rows, payload) {
  const score = Math.max(1, Math.min(100, Math.round(payload.score)));
  rows.push({
    generatedAt: nowIso,
    weekOf,
    clientEmail: payload.clientEmail || '',
    clientName: payload.clientName || '',
    phoneNumber: payload.phoneNumber || '',
    opportunityType: payload.opportunityType,
    priority: priorityFromScore(score),
    score,
    whyFlagged: payload.whyFlagged,
    recommendedAction: payload.recommendedAction,
    automationOwner: payload.automationOwner,
    relatedWorkflow: payload.relatedWorkflow,
    dueDate: payload.dueDate,
    status: payload.status || 'Open',
    sourceSignals: payload.sourceSignals,
    estimatedValue: Math.round(payload.estimatedValue || 0),
    lastActionAt: payload.lastActionAt || '',
    notes: payload.notes || ''
  });
}

const clients = $('Get All Clients').all().map(i => i.json);
const appointments = $('Get All Appointments').all().map(i => i.json);
const apptsByEmail = new Map();
for (const appt of appointments) {
  const email = String(appt['Client Email'] || '').toLowerCase().trim();
  if (!email) continue;
  if (!apptsByEmail.has(email)) apptsByEmail.set(email, []);
  apptsByEmail.get(email).push(appt);
}

const rows = [];
for (const client of clients) {
  const email = String(client['Client Email'] || '').toLowerCase().trim();
  if (!email) continue;
  if (String(client['Opted Out'] || '').toLowerCase() === 'yes') continue;

  const name = client['Client Name'] || 'Unknown client';
  const phone = client['Phone Number'] || '';
  const service = client['Service Interest'] || 'General Inquiry';
  const status = client['Status'] || '';
  const visits = parseInt(client['Total Visits'] || 0, 10) || 0;
  const spend = money(client['Total Spend']);
  const avgValue = spend > 0 && visits > 0 ? spend / visits : 350;
  const followUps = parseInt(client['Follow-Up Count'] || 0, 10) || 0;
  const createdDays = daysSince(client['Created Date']);
  const lastVisitDays = daysSince(client['Last Visit Date']);
  const clientAppts = apptsByEmail.get(email) || [];
  const noShows = clientAppts.filter(a => a['Status'] === 'No-Show');
  const cancelled = clientAppts.filter(a => a['Status'] === 'Cancelled');
  const scheduledUpcoming = clientAppts.filter(a => a['Status'] === 'Scheduled' && daysUntil(a['Appointment Date']) !== null && daysUntil(a['Appointment Date']) >= 0);

  if (status === 'New Inquiry' && createdDays !== null && createdDays >= 1 && followUps < 3) {
    pushOpportunity(rows, {
      clientEmail: email,
      clientName: name,
      phoneNumber: phone,
      opportunityType: 'Unbooked Consultation',
      score: 55 + Math.min(25, createdDays * 4) + (followUps === 0 ? 10 : 0),
      whyFlagged: `${createdDays} day(s) since inquiry, ${followUps}/3 follow-ups sent`,
      recommendedAction: 'Follow up with booking-focused consult message',
      automationOwner: followUps < 3 ? 'Automated' : 'Staff Required',
      relatedWorkflow: 'Workflow 2 - Appointment Follow-Up',
      dueDate: dueDate(0),
      sourceSignals: `Status=${status}; Service=${service}; Created=${client['Created Date'] || ''}; FollowUps=${followUps}`,
      estimatedValue: avgValue,
      lastActionAt: client['Last Follow-Up Date'] || '',
      notes: 'High-speed inquiry follow-up is the fastest recovery lever.'
    });
  }

  if (noShows.length > 0) {
    const latestNoShow = noShows.map(a => asDate(a['Appointment Date'])).filter(Boolean).sort((a, b) => b - a)[0];
    const noShowAge = latestNoShow ? Math.floor((now - latestNoShow) / 86400000) : null;
    if (noShowAge !== null && noShowAge <= 30) {
      pushOpportunity(rows, {
        clientEmail: email,
        clientName: name,
        phoneNumber: phone,
        opportunityType: 'No-Show Recovery',
        score: 82 + Math.min(12, noShows.length * 4) - Math.min(20, noShowAge),
        whyFlagged: `${noShows.length} no-show(s), latest ${noShowAge} day(s) ago`,
        recommendedAction: 'Recover missed appointment and offer quick rebook window',
        automationOwner: 'Automated',
        relatedWorkflow: 'Workflow 2 - Appointment Follow-Up',
        dueDate: dueDate(0),
        sourceSignals: `LatestNoShowDays=${noShowAge}; Service=${service}; NoShowCount=${noShows.length}`,
        estimatedValue: avgValue,
        lastActionAt: client['Last Follow-Up Date'] || '',
        notes: 'No-shows are paid demand already close to booking again.'
      });
    }
  }

  if (lastVisitDays !== null && lastVisitDays >= 60 && status !== 'New Inquiry') {
    let bucket = '60-Day Rebook';
    let baseScore = 65;
    let action = 'Send warm rebook prompt based on previous treatment cycle';
    if (lastVisitDays >= 180) { bucket = '180-Day Win-Back'; baseScore = 75; action = 'Send personal win-back note or owner-led check-in'; }
    else if (lastVisitDays >= 90) { bucket = '90-Day Reactivation'; baseScore = 78; action = 'Send reactivation offer or personal return invitation'; }
    pushOpportunity(rows, {
      clientEmail: email,
      clientName: name,
      phoneNumber: phone,
      opportunityType: bucket,
      score: baseScore + Math.min(10, visits * 2) + Math.min(10, avgValue / 100),
      whyFlagged: `${lastVisitDays} day(s) since last visit`,
      recommendedAction: action,
      automationOwner: 'Automated',
      relatedWorkflow: 'Workflow 4 - Client Reactivation',
      dueDate: dueDate(1),
      sourceSignals: `LastVisitDays=${lastVisitDays}; Visits=${visits}; Spend=${spend}; Service=${service}`,
      estimatedValue: avgValue,
      lastActionAt: client['Last Promo Month'] || '',
      notes: visits >= 3 || client['VIP Status'] === 'VIP' ? 'Treat as priority return client.' : 'Standard reactivation candidate.'
    });
  }

  if (scheduledUpcoming.length > 0) {
    const soonest = scheduledUpcoming.map(a => ({ row: a, days: daysUntil(a['Appointment Date']) })).sort((a, b) => a.days - b.days)[0];
    if (soonest && soonest.days <= 3) {
      pushOpportunity(rows, {
        clientEmail: email,
        clientName: name,
        phoneNumber: phone,
        opportunityType: 'Upcoming Appointment Protection',
        score: 60 + (soonest.days <= 1 ? 18 : 8),
        whyFlagged: `Appointment in ${soonest.days} day(s)`,
        recommendedAction: 'Make sure reminders and prep instructions are sent',
        automationOwner: 'Automated',
        relatedWorkflow: 'Workflow 2 - Appointment Follow-Up',
        dueDate: dueDate(0),
        sourceSignals: `AppointmentDate=${soonest.row['Appointment Date']}; Service=${soonest.row['Service'] || service}`,
        estimatedValue: money(soonest.row['Revenue']) || avgValue,
        lastActionAt: client['Last Follow-Up Date'] || '',
        notes: 'Protect booked revenue before it becomes a no-show.'
      });
    }
  }

  if (cancelled.length > 0) {
    const latestCancelled = cancelled.map(a => asDate(a['Appointment Date'])).filter(Boolean).sort((a, b) => b - a)[0];
    const cancelAge = latestCancelled ? Math.floor((now - latestCancelled) / 86400000) : null;
    if (cancelAge !== null && cancelAge <= 21 && scheduledUpcoming.length === 0) {
      pushOpportunity(rows, {
        clientEmail: email,
        clientName: name,
        phoneNumber: phone,
        opportunityType: 'Cancelled Consultation Recovery',
        score: 72 - Math.min(18, cancelAge) + Math.min(10, visits * 2),
        whyFlagged: `Cancelled ${cancelAge} day(s) ago and no new appointment booked`,
        recommendedAction: 'Ask whether they want the next available consult slot',
        automationOwner: 'Staff Required',
        relatedWorkflow: 'Workflow 2 - Appointment Follow-Up',
        dueDate: dueDate(0),
        sourceSignals: `CancelledDays=${cancelAge}; Service=${service}`,
        estimatedValue: avgValue,
        lastActionAt: client['Last Follow-Up Date'] || '',
        notes: 'Use a human tone if cancellation reason is unknown.'
      });
    }
  }
}

rows.sort((a, b) => b.score - a.score);
const topRows = rows.slice(0, 25).map((row, index) => ({ json: { ...row, priorityRank: index + 1 } }));
if (topRows.length === 0) {
  return [{ json: { generatedAt: nowIso, weekOf, priorityRank: 0, clientEmail: 'system', clientName: 'No opportunities flagged', phoneNumber: '', opportunityType: 'No Action', priority: 'Low', score: 0, whyFlagged: 'No qualifying recovery opportunities found this week', recommendedAction: 'Keep monitoring', automationOwner: 'System', relatedWorkflow: 'Workflow 10 - Revenue Recovery Prioritization', dueDate: weekOf, status: 'Completed', sourceSignals: 'none', estimatedValue: 0, lastActionAt: '', notes: '' } }];
}
return topRows;
